 "@type": "Recipe",
 "name": "Spicy Chili Garlic Noodles",
 "author": {
  "@type": "Person",
  "name": "Claire Cary"
 },
 "description": "These spicy chili garlic noodles are ready in about 15 minutes and FULL of flavor. They&#039;re gluten free and vegan but delicious with some extra stir fried veggies and your choice of protein!",
 "datePublished": "2023-06-27T08:00:00+00:00",
 "image": [
  "https://eatwithclarity.com/wp-content/uploads/2021/02/spicy-chili-noodles.jpg",
  "https://eatwithclarity.com/wp-content/uploads/2021/02/spicy-chili-noodles-500x500.jpg",
  "https://eatwithclarity.com/wp-content/uploads/2021/02/spicy-chili-noodles-500x375.jpg",
  "https://eatwithclarity.com/wp-content/uploads/2021/02/spicy-chili-noodles-480x270.jpg"
 ],
 "recipeYield": [
  "4",
  "4 servings"
 ],
 "prepTime": "PT5M",
 "cookTime": "PT15M",
 "totalTime": "PT20M",
 "recipeIngredient": [
  "8 ounces rice noodles (I used wide rice noodles)",
  "2  shallots (sliced)",
  "5 cloves garlic (minced)",
  "1/3 cup chopped scallions/green onions (just the white part, save the green for garnish!)",
  "1 tablespoon fresh grated ginger",
  "1 tablespoon oil (I used olive, vegetable oil works too!)",
  "4-5 tablespoons low sodium soy sauce or tamari (depending on how salty/saucy you like it)",
  "1-3 tablespoons chili garlic sauce (depending on brand and spice preference, click for the one I used)",
  "1 tablespoon brown sugar (can sub coconut sugar)",
  "1 tablespoon sriracha (more or less to taste)",
  "2 teaspoons rice vinegar",
  "1 tablespoon toasted sesame oil",
  "1/2 tsp red pepper flakes (optional for extra spice)"
 ],
 "recipeInstructions": [
  {
   "@type": "HowToStep",
   "text": "Bring a large pot of water to a boil and cook noodles according to package instructions.",
   "name": "cook noodles",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-0"
  },
  {
   "@type": "HowToStep",
   "text": "Add the shallots and garlic to a pot and saute with the oil until browned, about 5 minutes.",
   "name": "saute shallot",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-1"
  },
  {
   "@type": "HowToStep",
   "text": "Add the white part of the scallions and the grated ginger and saute for 2-3 more minutes.",
   "name": "add scallions",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-2"
  },
  {
   "@type": "HowToStep",
   "text": "Add in all remaining sauce ingredients and whisk together. Start on the low end of the recommended amounts of sriracha and chili sauce (1 tbsp or less for each).",
   "name": "whisk sauce",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-3"
  },
  {
   "@type": "HowToStep",
   "text": "It&#39;s very easy to make it more spicy if you want, but if it ends up too spicy for you, it&#39;s hard to tone it down! Everyone has different tolerance levels, hence the big ranges.",
   "name": "adjust spice",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-4"
  },
  {
   "@type": "HowToStep",
   "text": "When the noodles are done cooking, combine with the sauce and toss until well coated. Let simmer for a few minutes to allow the noodles to absorb the flavors. I also tossed in two diced roasted red peppers, but you can also add in any sauteed veggies you like!",
   "name": "add sauce to noodles",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-5"
  },
  {
   "@type": "HowToStep",
   "text": "Taste and adjust flavors as desired. The first bite might not seem that spicy, but it gets spicier the more you eat, so have a few bites before you decide to add extra sriracha or red chili flakes!",
   "name": "taste",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-6"
  },
  {
   "@type": "HowToStep",
   "text": "Serve as is or with any other vegetables or protein of choice. I love adding in bok choy, carrot or cabbage with chicken or tofu.",
   "name": "add veggies",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-7"
  },
  {
   "@type": "HowToStep",
   "text": "Top with red chili flakes for more spice and the remaining chopped scallions. Enjoy!",
   "name": "serve",
   "url": "https://eatwithclarity.com/spicy-chili-garlic-noodles/#wprm-recipe-26464-step-0-8"
  }
 ],
